 ('notebook-register-tabs','縦の登録番号と横の見出しをずらし、現在の資料を示す。','${--choice-base:#e7e4db;--choice-muted:#565e61;--choice-on:#203740;--choice-accent:#415d69;--choice-radius:0}$>.sop-choice-list{background:#e7e4db;border:1px solid #88969b;padding:4px;gap:1px}$ .sop-choice-marker{display:none}$ .sop-choice-item{border-right:1px solid #929d9e;gap:8px;align-items:baseline;padding:12px 9px}$ .sop-choice-index{display:block;writing-mode:vertical-rl;font:9px Consolas}$ .sop-choice-item[data-selected=true]{background:#c8d2d2;border-bottom:4px solid #577983}$ .sop-choice-panel{background:#25343c;border-radius:0;border-top:0}'),
