 ('narrow-gate-link','狭い縦の門の間から、ラベルと矢印が移動方向を示す。','${--sop-link-ink:#d2dcec;padding:14px 26px;border-left:3px solid #7590b0;border-right:3px solid #7590b0;border-radius:0;background:#20334c;gap:15px;transition:padding .55s,border-color .55s}$ .sop-link-icon{transform:rotate(45deg)}$:hover{padding-left:33px;padding-right:19px;border-color:#b8cee6}','A'),
